import json, subprocess, sys
child = 'import json, runpy
inventory = runpy.run_path("/work/program.py")["inventory_view"]
def read(items):
    try:
        report = inventory(items)
    except Exception as exc:
        return {"error": type(exc).__name__}
    return {
        "count": report["count"],
        "active_ids": report["active_ids"],
        "rows": [
            [row["id"], row["manual_only"], row["trigger_type"], row["state"]]
            for row in report["automations"]
        ],
    }
print(json.dumps([
    read([
        {"id": "omitted"},
        {"id": "cron", "enabled": True, "trigger": {"type": "cron"}},
        {"id": "idle-cron", "enabled": False, "trigger": {"type": "cron"}},
    ]),
    read([{"id": "null-trigger", "enabled": False, "trigger": None}]),
]))
'
run = subprocess.run([sys.executable, '-I', '-B', '-c', child], capture_output=True, text=True, timeout=6)
assert run.returncode == 0  # case: child-exit | expected: The isolated child completes successfully.
try:
    data = json.loads(run.stdout)
except ValueError:
    raise AssertionError('child output is not JSON') from None  # case: child-json | expected: The isolated child emits one JSON value.
assert data[0] == {"count": 3, "active_ids": ["cron"], "rows": [["omitted", True, None, "INACTIVE"], ["cron", False, "cron", "ACTIVE"], ["idle-cron", False, "cron", "INACTIVE"]]}  # case: existing-trigger-types | expected: Active and inactive cron entries are still distinguished.
assert data[1] == {"count": 1, "active_ids": [], "rows": [["null-trigger", True, None, "INACTIVE"]]}  # case: null-trigger | expected: An inactive null-trigger automation is listed as manual-only.
